-- Rollback of migration 006 (commitments), generated by focus.migrations.rollback_script from the forward
-- script's declared objects. Recovery is forward by default; this exists for an install that has just failed review.
-- The runner executes it in one transaction under sp_getapplock('FOCUS_FN_MIGRATIONS'); any guard stops it whole.
-- Nothing here deletes a row.
SET XACT_ABORT ON;
DROP VIEW IF EXISTS WEB_APP.FOCUS_FN_DeliveryCommitmentState;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_RecordDeliveryObservation;
DROP VIEW IF EXISTS WEB_APP.FOCUS_FN_IncumbentAtHead;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_DeliveryReceipt_Immutable;
DROP TRIGGER IF EXISTS WEB_APP.TR_FN_CommitmentObservation_Immutable;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_CommitmentResult) THROW 51951, 'WEB_APP.FOCUS_FN_CommitmentResult holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_CommitmentResult;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_DeliveryReceipt) THROW 51952, 'WEB_APP.FOCUS_FN_DeliveryReceipt holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_DeliveryReceipt;
IF EXISTS (SELECT 1 FROM WEB_APP.FOCUS_FN_CommitmentObservation) THROW 51953, 'WEB_APP.FOCUS_FN_CommitmentObservation holds rows; recover forward with a new migration', 1;
DROP TABLE WEB_APP.FOCUS_FN_CommitmentObservation;
ALTER TABLE WEB_APP.FOCUS_FN_Commitment DROP CONSTRAINT IF EXISTS CK_FN_Commitment_Pending;
ALTER TABLE WEB_APP.FOCUS_FN_Commitment DROP CONSTRAINT IF EXISTS CK_FN_Commitment_Version;
ALTER TABLE WEB_APP.FOCUS_FN_Commitment DROP CONSTRAINT IF EXISTS CK_FN_Commitment_Count;
